import{j as k}from"./vendor-react-DzFdt34V.js";import{f as d,p as g,d as I,e as E,i as H,U as j}from"./LabKit-BbJl5ZU8.js";import{n as h}from"./notation-BaZ3uylG.js";import{D,d as L,a as B,b as W,c as S,g as A,e as Z,f as P,h as F,i as V,F as R,H as N,M as Q,j as U,S as O,k as Y,V as J,C as _,l as X,m as ee,L as ae,n as te,o as ie,J as oe,R as ne,p as C,q as se,r as re,s as de,t as le}from"./DivisibilityLab-Bu4N6ppF.js";import{c as ce,W as ue}from"./WorkedDetectiveGame-BlThUgDl.js";/* empty css                        */import"./index-B-aBnto3.js";import"./vendor-i18n-D_kkcOKx.js";import"./vendor-CAIZfmPq.js";import"./vendor-katex-CdCLdKXh.js";import"./NumberField-CeKiXUtE.js";import"./types-D0REvJHO.js";/* empty css                  */const e=(i,s,a,t)=>({eu:h(i).eu,es:h(s).es,en:h(t).en,ar:h(a).ar}),u=i=>h(i),me=[{id:801,prompt:e("Zein zatiketa da zehatza?","¿Qué división es exacta?","أي قسمة تامة؟","Which division is exact?"),options:[u("$35\\mathbin{:}6$"),u("$42\\mathbin{:}7$"),u("$50\\mathbin{:}8$")],correctIndex:1,explanation:e("$42=7\\cdot 6$: hondarra 0 da. Besteetan hondarra 5 eta 2 dira.","$42=7\\cdot 6$: el resto es 0. En las otras el resto es 5 y 2.","$42=7\\cdot 6$: الباقي 0. وفي الأخريين الباقي 5 و2.","$42=7\\cdot 6$: the remainder is 0. In the others the remainder is 5 and 2."),topic:"relation"},{id:802,prompt:e("Zein da 7ren multiploa?","¿Cuál es múltiplo de 7?","أي عدد مضاعف لـ 7؟","Which one is a multiple of 7?"),options:[u("$57$"),u("$27$"),u("$49$")],correctIndex:2,explanation:e("$49=7\\cdot 7$. Kontuz: 57 eta 27 7z amaitzen dira, baina $57=3\\cdot 19$ eta $27=3\\cdot 9$.","$49=7\\cdot 7$. Cuidado: 57 y 27 acaban en 7, pero $57=3\\cdot 19$ y $27=3\\cdot 9$.","$49=7\\cdot 7$. انتبه: 57 و27 ينتهيان بـ 7، لكن $57=3\\cdot 19$ و$27=3\\cdot 9$.","$49=7\\cdot 7$. Be careful: 57 and 27 end in 7, but $57=3\\cdot 19$ and $27=3\\cdot 9$."),topic:"multiples"},{id:803,prompt:e("Zenbat zatitzaile ditu 18k?","¿Cuántos divisores tiene 18?","كم قاسمًا للعدد 18؟","How many divisors does 18 have?"),options:[u("$4$"),u("$6$"),u("$5$")],correctIndex:1,explanation:e("$@DIV(18)=\\{1,2,3,6,9,18\\}$: sei zatitzaile.","$@DIV(18)=\\{1,2,3,6,9,18\\}$: seis divisores.","$@DIV(18)=\\{1,2,3,6,9,18\\}$: ستة قواسم.","$@DIV(18)=\\{1,2,3,6,9,18\\}$: six divisors."),topic:"divisors"},{id:804,prompt:e("Zein da 3rekin zatigarria?","¿Cuál es divisible por 3?","أي عدد يقبل القسمة على 3؟","Which one is divisible by 3?"),options:[u("$4111$"),u("$2025$"),u("$1000$")],correctIndex:1,explanation:e("$2+0+2+5=9$, 3ren multiploa. Besteetan batura 7 eta 1 da.","$2+0+2+5=9$, múltiplo de 3. En los otros la suma es 7 y 1.","$2+0+2+5=9$ وهو مضاعف لـ 3. وفي الآخرين المجموع 7 و1.","$2+0+2+5=9$, a multiple of 3. In the others the sum is 7 and 1."),topic:"criteria-sum"},{id:805,prompt:e("Zein da zenbaki lehena?","¿Cuál es un número primo?","أي عدد أولي؟","Which one is a prime number?"),options:[u("$51$"),u("$57$"),u("$53$")],correctIndex:2,explanation:e("53k 1 eta 53 ditu zatitzaile bakarrik. $51=3\\cdot 17$ eta $57=3\\cdot 19$.","53 solo tiene como divisores 1 y 53. $51=3\\cdot 17$ y $57=3\\cdot 19$.","للعدد 53 قاسمان فقط: 1 و53. أما $51=3\\cdot 17$ و$57=3\\cdot 19$.","53 has only 1 and 53 as divisors. $51=3\\cdot 17$ and $57=3\\cdot 19$."),topic:"primes"},{id:806,prompt:e("Zein da 72ren deskonposizioa biderkagai lehenetan?","¿Cuál es la descomposición de 72 en factores primos?","ما تحليل 72 إلى عوامل أولية؟","What is the prime factorisation of 72?"),options:[u("$2^{3}\\cdot 3^{2}$"),u("$8\\cdot 9$"),u("$2^{2}\\cdot 3^{3}$")],correctIndex:0,explanation:e("$72=8\\cdot 9=2^{3}\\cdot 3^{2}$. $8\\cdot 9$ ez da baliozkoa, 8 eta 9 ez direlako lehenak.","$72=8\\cdot 9=2^{3}\\cdot 3^{2}$. $8\\cdot 9$ no vale porque 8 y 9 no son primos.","$72=8\\cdot 9=2^{3}\\cdot 3^{2}$. والصيغة $8\\cdot 9$ غير مقبولة لأن 8 و9 ليسا أوليين.","$72=8\\cdot 9=2^{3}\\cdot 3^{2}$. $8\\cdot 9$ does not count, because 8 and 9 are not prime."),topic:"factorization"},{id:807,prompt:e("Zenbat da $@GCD(12,18)$?","¿Cuánto es el $@GCD(12,18)$?","كم يساوي $@GCD(12,18)$؟","What is $@GCD(12,18)$?"),options:[u("$6$"),u("$36$"),u("$3$")],correctIndex:0,explanation:e("$12=2^{2}\\cdot 3$ eta $18=2\\cdot 3^{2}$: komunak berretzaile txikienarekin, $2\\cdot 3=6$. 36 MKT da.","$12=2^{2}\\cdot 3$ y $18=2\\cdot 3^{2}$: comunes con el menor exponente, $2\\cdot 3=6$. 36 es el m.c.m.","$12=2^{2}\\cdot 3$ و$18=2\\cdot 3^{2}$: المشتركة بأصغر أس، $2\\cdot 3=6$. أما 36 فهو م.م.أ.","$12=2^{2}\\cdot 3$ and $18=2\\cdot 3^{2}$: common factors with the lowest exponent, $2\\cdot 3=6$. 36 is the LCM."),topic:"gcd"},{id:808,prompt:e("Bi argi 6 eta 8 segundoro pizten dira, eta orain batera piztu dira. Noiz piztuko dira berriro batera?","Dos luces se encienden cada 6 y cada 8 segundos, y ahora se han encendido juntas. ¿Cuándo volverán a coincidir?","ضوءان يضيئان كل 6 و8 ثوانٍ، وقد أضاءا معًا الآن. متى سيضيئان معًا مجددًا؟","Two lights come on every 6 and every 8 seconds, and they have just come on together. When will they next come on together?"),options:[e("24 s barru","Dentro de 24 s","بعد 24 ث","In 24 s"),e("48 s barru","Dentro de 48 s","بعد 48 ث","In 48 s"),e("2 s barru","Dentro de 2 s","بعد 2 ث","In 2 s")],correctIndex:0,explanation:e("Berriro bat etortzea → MKT. $@LCM(6,8)=2^{3}\\cdot 3=24$ s.","Volver a coincidir → m.c.m. $@LCM(6,8)=2^{3}\\cdot 3=24$ s.","التزامن مجددًا ← م.م.أ. $@LCM(6,8)=2^{3}\\cdot 3=24$ ث.","Light up together again → LCM $@LCM(6,8)=2^{3}\\cdot 3=24$ s."),topic:"which"}],v=i=>e(`Kalkulatu: ${i}`,`Calcula: ${i}`,`احسب: ${i}`,`Calculate: ${i}`),$e=[{id:1,stage:"multiples",prompt:e("Zein da 7ren bosgarren multiploa (0 kontatu gabe)?","¿Cuál es el quinto múltiplo de 7 (sin contar el 0)?","ما المضاعف الخامس للعدد 7 (دون احتساب 0)؟","What is the fifth multiple of 7 (not counting 0)?"),expected:d(35),hint:e("Biderkatu 7 bider 5.","Multiplica 7 por 5.","اضرب 7 في 5.","Multiply 7 by 5."),explanation:e("$\\mathrm{M}(7)=\\{7,14,21,28,35,\\dots\\}$","$\\mathrm{M}(7)=\\{7,14,21,28,35,\\dots\\}$","$\\mathrm{M}(7)=\\{7,14,21,28,35,\\dots\\}$","$\\mathrm{M}(7)=\\{7,14,21,28,35,\\dots\\}$")},{id:2,stage:"multiples",prompt:e("Zein da 100 baino handiagoa den 13ren multiplorik txikiena?","¿Cuál es el menor múltiplo de 13 mayor que 100?","ما أصغر مضاعف لـ 13 أكبر من 100؟","What is the smallest multiple of 13 greater than 100?"),expected:d(104),hint:e("Zatitu 100 : 13 eta begiratu zatidurari.","Divide 100 : 13 y fíjate en el cociente.","اقسم 100 : 13 وانظر إلى الناتج.","Divide 100 : 13 and look at the quotient."),explanation:e("$100\\mathbin{:}13=7$ eta hondarra 9. Hurrengo multiploa $13\\cdot 8=104$.","$100\\mathbin{:}13=7$ y resto 9. El siguiente múltiplo es $13\\cdot 8=104$.","$100\\mathbin{:}13=7$ والباقي 9. المضاعف التالي $13\\cdot 8=104$.","$100\\mathbin{:}13=7$ with remainder 9. The next multiple is $13\\cdot 8=104$.")},{id:3,stage:"multiples",prompt:e("Zenbat zatitzaile ditu 36k?","¿Cuántos divisores tiene 36?","كم قاسمًا للعدد 36؟","How many divisors does 36 have?"),expected:d(9),hint:e("Bilatu bikoteak: $1\\cdot 36$, $2\\cdot 18$…","Busca las parejas: $1\\cdot 36$, $2\\cdot 18$…","ابحث عن الأزواج: $1\\cdot 36$، $2\\cdot 18$…","Look for the pairs: $1\\cdot 36$, $2\\cdot 18$…"),explanation:e("$@DIV(36)=\\{1,2,3,4,6,9,12,18,36\\}$: 9 zatitzaile (6 bikotean behin bakarrik).","$@DIV(36)=\\{1,2,3,4,6,9,12,18,36\\}$: 9 divisores (el 6 se cuenta una vez).","$@DIV(36)=\\{1,2,3,4,6,9,12,18,36\\}$: تسعة قواسم (العدد 6 يُحسب مرة واحدة).","$@DIV(36)=\\{1,2,3,4,6,9,12,18,36\\}$: 9 divisors (6 is counted once).")},{id:4,stage:"multiples",prompt:e("Zein da $100\\mathbin{:}7$ zatiketaren hondarra?","¿Cuál es el resto de la división $100\\mathbin{:}7$?","ما باقي القسمة $100\\mathbin{:}7$؟","What is the remainder of the division $100\\mathbin{:}7$?"),expected:d(2),hint:e("$7\\cdot 14=98$.","$7\\cdot 14=98$.","$7\\cdot 14=98$.","$7\\cdot 14=98$."),explanation:e("$100=7\\cdot 14+2$: hondarra 2 da, beraz 100 ez da 7ren multiploa.","$100=7\\cdot 14+2$: el resto es 2, así que 100 no es múltiplo de 7.","$100=7\\cdot 14+2$: الباقي 2، إذن 100 ليس مضاعفًا لـ 7.","$100=7\\cdot 14+2$: the remainder is 2, so 100 is not a multiple of 7.")},{id:5,stage:"criteria",prompt:e("Zein zifra jarri behar da $35\\square$ zenbakian 2rekin eta 5ekin zatigarria izateko?","¿Qué cifra hay que poner en $35\\square$ para que sea divisible por 2 y por 5?","أي رقم نضع في $35\\square$ ليقبل القسمة على 2 و5؟","Which digit must go in $35\\square$ so that it is divisible by 2 and by 5?"),expected:d(0),hint:e("2rekin: azken zifra bikoitia. 5ekin: 0 edo 5.","Por 2: última cifra par. Por 5: 0 o 5.","على 2: الرقم الأخير زوجي. على 5: ‏0 أو 5.","For 2: last digit even. For 5: 0 or 5."),explanation:e("Bi baldintzak betetzen dituen zifra bakarra 0 da: 350.","La única cifra que cumple las dos condiciones es 0: 350.","الرقم الوحيد الذي يحقق الشرطين هو 0: ‏350.","The only digit that meets both conditions is 0: 350.")},{id:6,stage:"criteria",prompt:e("Zein zifra falta da $4\\square 2$ zenbakian 9rekin zatigarria izateko?","¿Qué cifra falta en $4\\square 2$ para que sea divisible por 9?","ما الرقم الناقص في $4\\square 2$ ليقبل القسمة على 9؟","Which digit is missing in $4\\square 2$ so that it is divisible by 9?"),expected:d(3),hint:e("$4+\\square+2$ 9 izan behar da.","$4+\\square+2$ tiene que dar 9.","يجب أن يساوي $4+\\square+2$ العدد 9.","$4+\\square+2$ must add up to 9."),explanation:e("$4+3+2=9$: 432. (Batura 18 izateko 12 behar litzateke, eta ez da zifra bat.)","$4+3+2=9$: 432. (Para sumar 18 haría falta 12, que no es una cifra.)","$4+3+2=9$: ‏432. (ولكي يكون المجموع 18 نحتاج 12، وهو ليس رقمًا واحدًا.)","$4+3+2=9$: 432. (To make 18 you would need 12, which is not a digit.)")},{id:7,stage:"criteria",prompt:e("Zein da $71\\square$ 3rekin zatigarria egiten duen zifrarik txikiena?","¿Cuál es la menor cifra que hace $71\\square$ divisible por 3?","ما أصغر رقم يجعل $71\\square$ يقبل القسمة على 3؟","What is the smallest digit that makes $71\\square$ divisible by 3?"),expected:d(1),hint:e("$7+1=8$. Zenbat falta da 3ren hurrengo multiplora iristeko?","$7+1=8$. ¿Cuánto falta para el siguiente múltiplo de 3?","$7+1=8$. كم ينقص للوصول إلى مضاعف 3 التالي؟","$7+1=8$. How much more is needed to reach the next multiple of 3?"),explanation:e("$7+1+1=9$: 711. 4 eta 7 ere balio dute, baina 1 da txikiena.","$7+1+1=9$: 711. También valen 4 y 7, pero 1 es la menor.","$7+1+1=9$: ‏711. ويصلح أيضًا 4 و7، لكن 1 هو الأصغر.","$7+1+1=9$: 711. 4 and 7 also work, but 1 is the smallest.")},{id:8,stage:"criteria",prompt:e("Aplikatu 11ren irizpidea 8294 zenbakiari. Zenbat ematen du kenketak (posizio bikoitiak − bakoitiak)?","Aplica el criterio del 11 a 8 294. ¿Cuánto da la resta (lugares pares − impares)?","طبّق قاعدة 11 على 8294. كم ناتج الطرح (المواقع الزوجية − الفردية)؟","Apply the divisibility rule for 11 to 8,294. What is the result of the subtraction (even places − odd places)?"),expected:d(11),hint:e("Eskuinetik hasita: 4 (1.), 9 (2.), 2 (3.), 8 (4.).","Empezando por la derecha: 4 (1.º), 9 (2.º), 2 (3.º), 8 (4.º).","من اليمين: 4 (الأول)، 9 (الثاني)، 2 (الثالث)، 8 (الرابع).","Starting from the right: 4 (1st), 9 (2nd), 2 (3rd), 8 (4th)."),explanation:e("$(9+8)-(4+2)=17-6=11$: 11ren multiploa, beraz 8294 11rekin zatigarria da ($8294=11\\cdot 754$).","$(9+8)-(4+2)=17-6=11$: múltiplo de 11, luego 8294 es divisible por 11 ($8294=11\\cdot 754$).","$(9+8)-(4+2)=17-6=11$: مضاعف لـ 11، إذن 8294 يقبل القسمة على 11 ($8294=11\\cdot 754$).","$(9+8)-(4+2)=17-6=11$: a multiple of 11, so 8,294 is divisible by 11 ($8\\,294=11\\cdot 754$).")},{id:9,stage:"criteria",prompt:e("7ren irizpidea 581 zenbakiarekin: kendu azken zifra eta kendu haren bikoitza. Zer zenbaki lortzen duzu?","Criterio del 7 con 581: quita la última cifra y resta su doble. ¿Qué número obtienes?","قاعدة 7 مع 581: احذف الرقم الأخير واطرح ضعفه. ما العدد الناتج؟","Divisibility rule for 7 with 581: remove the last digit and subtract twice that digit from what is left. What number do you get?"),expected:d(56),hint:e("$58-2\\cdot 1$","$58-2\\cdot 1$","$58-2\\cdot 1$","$58-2\\cdot 1$"),explanation:e("$58-2=56=7\\cdot 8$: beraz 581 7rekin zatigarria da ($581=7\\cdot 83$).","$58-2=56=7\\cdot 8$: luego 581 es divisible por 7 ($581=7\\cdot 83$).","$58-2=56=7\\cdot 8$: إذن 581 يقبل القسمة على 7 ($581=7\\cdot 83$).","$58-2=56=7\\cdot 8$: so 581 is divisible by 7 ($581=7\\cdot 83$).")},{id:10,stage:"primes",prompt:e("Zenbat zenbaki lehen daude 20 eta 40 artean?","¿Cuántos números primos hay entre 20 y 40?","كم عددًا أوليًا بين 20 و40؟","How many prime numbers are there between 20 and 40?"),expected:d(4),hint:e("Baztertu bikoitiak eta 3ren eta 5en multiploak.","Descarta los pares y los múltiplos de 3 y de 5.","استبعد الزوجية ومضاعفات 3 و5.","Rule out the even numbers and the multiples of 3 and of 5."),explanation:e("23, 29, 31 eta 37. (21, 27, 33 eta 39 3ren multiploak dira; 35 5ena.)","23, 29, 31 y 37. (21, 27, 33 y 39 son múltiplos de 3; 35, de 5.)","23 و29 و31 و37. (21 و27 و33 و39 مضاعفات لـ 3، و35 لـ 5.)","23, 29, 31 and 37. (21, 27, 33 and 39 are multiples of 3; 35 is a multiple of 5.)")},{id:11,stage:"primes",prompt:e("$84=2^{a}\\cdot 3\\cdot 7$. Zenbat da $a$?","$84=2^{a}\\cdot 3\\cdot 7$. ¿Cuánto vale $a$?","$84=2^{a}\\cdot 3\\cdot 7$. كم قيمة $a$؟","$84=2^{a}\\cdot 3\\cdot 7$. What is the value of $a$?"),expected:d(2),hint:e("Zatitu 84 2z behin eta berriz.","Divide 84 entre 2 una y otra vez.","اقسم 84 على 2 مرة بعد مرة.","Divide 84 by 2 again and again."),explanation:e("$84\\mathbin{:}2=42$, $42\\mathbin{:}2=21$, 21 bakoitia da: $84=2^{2}\\cdot 3\\cdot 7$.","$84\\mathbin{:}2=42$, $42\\mathbin{:}2=21$, y 21 es impar: $84=2^{2}\\cdot 3\\cdot 7$.","$84\\mathbin{:}2=42$ و$42\\mathbin{:}2=21$، و21 فردي: $84=2^{2}\\cdot 3\\cdot 7$.","$84\\mathbin{:}2=42$, $42\\mathbin{:}2=21$, and 21 is odd: $84=2^{2}\\cdot 3\\cdot 7$.")},{id:12,stage:"primes",prompt:e("Zein zenbaki da $2^{3}\\cdot 3\\cdot 5^{2}$?","¿Qué número es $2^{3}\\cdot 3\\cdot 5^{2}$?","ما العدد $2^{3}\\cdot 3\\cdot 5^{2}$؟","What number is $2^{3}\\cdot 3\\cdot 5^{2}$?"),expected:d(600),hint:e("$2^{3}=8$ eta $5^{2}=25$.","$2^{3}=8$ y $5^{2}=25$.","$2^{3}=8$ و$5^{2}=25$.","$2^{3}=8$ and $5^{2}=25$."),explanation:e("$8\\cdot 3\\cdot 25=24\\cdot 25=600$.","$8\\cdot 3\\cdot 25=24\\cdot 25=600$.","$8\\cdot 3\\cdot 25=24\\cdot 25=600$.","$8\\cdot 3\\cdot 25=24\\cdot 25=600$.")},{id:13,stage:"gcd-lcm",prompt:v("$@GCD(48,60)$"),expected:d(12),hint:e("$48=2^{4}\\cdot 3$ eta $60=2^{2}\\cdot 3\\cdot 5$.","$48=2^{4}\\cdot 3$ y $60=2^{2}\\cdot 3\\cdot 5$.","$48=2^{4}\\cdot 3$ و$60=2^{2}\\cdot 3\\cdot 5$.","$48=2^{4}\\cdot 3$ and $60=2^{2}\\cdot 3\\cdot 5$."),explanation:e("Komunak berretzaile txikienarekin: $2^{2}\\cdot 3=12$.","Comunes con el menor exponente: $2^{2}\\cdot 3=12$.","المشتركة بأصغر أس: $2^{2}\\cdot 3=12$.","Common factors with the lowest exponent: $2^{2}\\cdot 3=12$.")},{id:14,stage:"gcd-lcm",prompt:v("$@GCD(36,54,90)$"),expected:d(18),hint:e("$36=2^{2}\\cdot 3^{2}$, $54=2\\cdot 3^{3}$, $90=2\\cdot 3^{2}\\cdot 5$.","$36=2^{2}\\cdot 3^{2}$, $54=2\\cdot 3^{3}$, $90=2\\cdot 3^{2}\\cdot 5$.","$36=2^{2}\\cdot 3^{2}$، $54=2\\cdot 3^{3}$، $90=2\\cdot 3^{2}\\cdot 5$.","$36=2^{2}\\cdot 3^{2}$, $54=2\\cdot 3^{3}$, $90=2\\cdot 3^{2}\\cdot 5$."),explanation:e("Hiruretan daude 2 eta 3: $2\\cdot 3^{2}=18$. 5 ez da komuna.","Están en los tres el 2 y el 3: $2\\cdot 3^{2}=18$. El 5 no es común.","العاملان 2 و3 موجودان في الثلاثة: $2\\cdot 3^{2}=18$. أما 5 فليس مشتركًا.","The 2 and the 3 are in all three: $2\\cdot 3^{2}=18$. The 5 is not common.")},{id:15,stage:"gcd-lcm",prompt:v("$@LCM(12,18)$"),expected:d(36),hint:e("$12=2^{2}\\cdot 3$ eta $18=2\\cdot 3^{2}$.","$12=2^{2}\\cdot 3$ y $18=2\\cdot 3^{2}$.","$12=2^{2}\\cdot 3$ و$18=2\\cdot 3^{2}$.","$12=2^{2}\\cdot 3$ and $18=2\\cdot 3^{2}$."),explanation:e("Guztiak berretzaile handienarekin: $2^{2}\\cdot 3^{2}=36$.","Todos con el mayor exponente: $2^{2}\\cdot 3^{2}=36$.","الكل بأكبر أس: $2^{2}\\cdot 3^{2}=36$.","All with the highest exponent: $2^{2}\\cdot 3^{2}=36$.")},{id:16,stage:"gcd-lcm",prompt:v("$@LCM(8,12,15)$"),expected:d(120),hint:e("$8=2^{3}$, $12=2^{2}\\cdot 3$, $15=3\\cdot 5$.","$8=2^{3}$, $12=2^{2}\\cdot 3$, $15=3\\cdot 5$.","$8=2^{3}$، $12=2^{2}\\cdot 3$، $15=3\\cdot 5$.","$8=2^{3}$, $12=2^{2}\\cdot 3$, $15=3\\cdot 5$."),explanation:e("$2^{3}\\cdot 3\\cdot 5=120$.","$2^{3}\\cdot 3\\cdot 5=120$.","$2^{3}\\cdot 3\\cdot 5=120$.","$2^{3}\\cdot 3\\cdot 5=120$.")},{id:17,stage:"problems",prompt:e("60 cm eta 84 cm-ko bi zinta ditugu. Zati berdinetan moztu nahi ditugu, ahalik eta luzeenak eta ezer soberan gabe. Zenbat cm izango ditu zati bakoitzak?","Tenemos dos cintas de 60 cm y 84 cm. Queremos cortarlas en trozos iguales, lo más largos posible y sin que sobre nada. ¿Cuántos cm medirá cada trozo?","لدينا شريطان طولهما 60 سم و84 سم. نريد قصهما إلى قطع متساوية بأطول ما يمكن دون أن يبقى شيء. كم سنتيمترًا سيكون طول كل قطعة؟","We have two ribbons, 60 cm and 84 cm long. We want to cut them into equal pieces that are as long as possible, with nothing left over. How long will each piece be, in cm?"),expected:d(12),hint:e("Zatitu, soberakinik gabe, handiena → ZKH.","Repartir sin que sobre, lo más grande posible → m.c.d.","تقسيم دون باقٍ وبأكبر طول ← ق.م.أ.","Share with nothing left over, as large as possible → GCD."),explanation:e("$@GCD(60,84)=2^{2}\\cdot 3=12$: zati bakoitzak 12 cm (5 + 7 = 12 zati).","$@GCD(60,84)=2^{2}\\cdot 3=12$: cada trozo medirá 12 cm (5 + 7 = 12 trozos).","$@GCD(60,84)=2^{2}\\cdot 3=12$: طول كل قطعة 12 سم (5 + 7 = 12 قطعة).","$@GCD(60,84)=2^{2}\\cdot 3=12$: each piece will be 12 cm long (5 + 7 = 12 pieces).")},{id:18,stage:"problems",prompt:e("Itsasargi bat 12 segundoro pizten da eta beste bat 20 segundoro. Batera piztu badira, zenbat segundo pasako dira berriro batera piztu arte?","Un faro se enciende cada 12 segundos y otro cada 20. Si se han encendido juntos, ¿cuántos segundos pasarán hasta que vuelvan a coincidir?","منارة تضيء كل 12 ثانية وأخرى كل 20. إذا أضاءتا معًا، فكم ثانية تمر حتى تضيئا معًا مجددًا؟","One lighthouse light comes on every 12 seconds and another every 20. If they have just come on together, how many seconds will pass before they come on together again?"),expected:d(60),hint:e("Berriro bat etorri → MKT.","Volver a coincidir → m.c.m.","التزامن مجددًا ← م.م.أ.","Light up together again → LCM."),explanation:e("$@LCM(12,20)=2^{2}\\cdot 3\\cdot 5=60$: 60 segundo barru (minutu bat).","$@LCM(12,20)=2^{2}\\cdot 3\\cdot 5=60$: dentro de 60 segundos (un minuto).","$@LCM(12,20)=2^{2}\\cdot 3\\cdot 5=60$: بعد 60 ثانية (دقيقة واحدة).","$@LCM(12,20)=2^{2}\\cdot 3\\cdot 5=60$: in 60 seconds (one minute).")}],be=[{id:101,stage:"problems",context:"starter",points:10,prompt:e("Anek 24 marrubi-gozoki eta 36 limoi-gozoki ditu. Poltsa berdinak egin nahi ditu, zapore bakarrekoak eta ahalik eta gozoki gehienekin. Zenbat gozoki sartuko ditu poltsa bakoitzean?","Ane tiene 24 caramelos de fresa y 36 de limón. Quiere hacer bolsas iguales, de un solo sabor y con el mayor número posible de caramelos. ¿Cuántos caramelos pondrá en cada bolsa?","لدى آنه 24 حلوى بالفراولة و36 بالليمون. تريد صنع أكياس متساوية بنكهة واحدة وبأكبر عدد ممكن من الحلوى. كم حلوى ستضع في كل كيس؟","Ane has 24 strawberry sweets and 36 lemon sweets. She wants to make bags that are all the same, with only one flavour in each and as many sweets as possible. How many sweets will she put in each bag?"),expected:d(12),hint:e("Zatitu eta handiena → ZKH.","Repartir y lo más grande → m.c.d.","تقسيم وأكبر عدد ← ق.م.أ.","Share out, as large as possible → GCD."),explanation:e("$@GCD(24,36)=12$: 12 gozoki poltsa bakoitzean (2 poltsa marrubi eta 3 limoi).","$@GCD(24,36)=12$: 12 caramelos por bolsa (2 bolsas de fresa y 3 de limón).","$@GCD(24,36)=12$: ‏12 حلوى في كل كيس (كيسان بالفراولة و3 بالليمون).","$@GCD(24,36)=12$: 12 sweets per bag (2 bags of strawberry and 3 of lemon).")},{id:102,stage:"problems",context:"starter",points:10,prompt:e("Mikel 4 egunez behin joaten da igerilekura eta Nora 6 egunez behin. Gaur bat egin dute. Zenbat egun barru egingo dute bat berriro?","Mikel va a la piscina cada 4 días y Nora cada 6. Hoy han coincidido. ¿Dentro de cuántos días volverán a coincidir?","يذهب ميكيل إلى المسبح كل 4 أيام ونورا كل 6. التقيا اليوم. بعد كم يومًا سيلتقيان مجددًا؟","Mikel goes to the pool every 4 days and Nora every 6. Today they were both there. In how many days will they both be there again?"),expected:d(12),hint:e("Berriro bat etorri → MKT.","Volver a coincidir → m.c.m.","التزامن ← م.م.أ.","Light up together again → LCM."),explanation:e("$@LCM(4,6)=12$: 12 egun barru.","$@LCM(4,6)=12$: dentro de 12 días.","$@LCM(4,6)=12$: بعد 12 يومًا.","$@LCM(4,6)=12$: in 12 days.")},{id:103,stage:"multiples",context:"starter",points:10,prompt:e("24 aulki ilara berdinetan jarri nahi dira. Zenbat modu desberdinetan egin daiteke (ilara bakarra ere kontatuta)?","Se quieren colocar 24 sillas en filas iguales. ¿De cuántas formas distintas se puede hacer (contando una sola fila)?","نريد ترتيب 24 كرسيًا في صفوف متساوية. بكم طريقة مختلفة يمكن ذلك (مع احتساب صف واحد)؟","24 chairs are to be arranged in equal rows. In how many different ways can this be done (including the option of a single row)?"),expected:d(8),hint:e("Ilara kopuru bakoitza 24ren zatitzaile bat da.","Cada número de filas es un divisor de 24.","كل عدد صفوف هو قاسم للعدد 24.","Each number of rows is a divisor of 24."),explanation:e("$@DIV(24)=\\{1,2,3,4,6,8,12,24\\}$: 8 modu.","$@DIV(24)=\\{1,2,3,4,6,8,12,24\\}$: 8 formas.","$@DIV(24)=\\{1,2,3,4,6,8,12,24\\}$: ‏8 طرق.","$@DIV(24)=\\{1,2,3,4,6,8,12,24\\}$: 8 ways.")},{id:104,stage:"problems",context:"advanced",points:20,prompt:e("360 cm × 240 cm-ko lurzorua ahalik eta handienak diren lauza karratuekin estali nahi da, bat ere moztu gabe. Zenbat cm izango ditu lauza bakoitzaren aldeak?","Un suelo de 360 cm × 240 cm se quiere cubrir con baldosas cuadradas lo más grandes posible, sin cortar ninguna. ¿Cuántos cm medirá el lado de cada baldosa?","نريد تغطية أرضية مساحتها 360 سم × 240 سم ببلاط مربع بأكبر حجم ممكن دون قص أي بلاطة. كم سنتيمترًا طول ضلع كل بلاطة؟","A floor measuring 360 cm × 240 cm is to be covered with square tiles as large as possible, without cutting any. How long is the side of each tile, in cm?"),expected:d(120),hint:e("Aldeak bi neurriak zatitu behar ditu → ZKH.","El lado tiene que dividir las dos medidas → m.c.d.","يجب أن يقسم الضلع البعدين كليهما ← ق.م.أ.","The side must divide both measurements → GCD."),explanation:e("$360=2^{3}\\cdot 3^{2}\\cdot 5$, $240=2^{4}\\cdot 3\\cdot 5$ → $@GCD=2^{3}\\cdot 3\\cdot 5=120$ cm (6 lauza).","$360=2^{3}\\cdot 3^{2}\\cdot 5$, $240=2^{4}\\cdot 3\\cdot 5$ → $@GCD=2^{3}\\cdot 3\\cdot 5=120$ cm (6 baldosas).","$360=2^{3}\\cdot 3^{2}\\cdot 5$، $240=2^{4}\\cdot 3\\cdot 5$ ← $@GCD=2^{3}\\cdot 3\\cdot 5=120$ سم (6 بلاطات).","$360=2^{3}\\cdot 3^{2}\\cdot 5$, $240=2^{4}\\cdot 3\\cdot 5$ → $@GCD=2^{3}\\cdot 3\\cdot 5=120$ cm (6 tiles).")},{id:105,stage:"problems",context:"advanced",points:20,prompt:e("78 limoi-gaileta, 130 esne-gaileta eta 156 ezti-gaileta ditugu. Kutxa berdinak bete nahi ditugu, mota bakarrekoak eta ahalik eta gaileta gehienekin. Zenbat kutxa behar dira guztira?","Tenemos 78 galletas de limón, 130 de nata y 156 de miel. Queremos llenar cajas iguales, de un solo tipo y con el mayor número posible de galletas. ¿Cuántas cajas hacen falta en total?","لدينا 78 بسكويتة بالليمون و130 بالقشدة و156 بالعسل. نريد ملء صناديق متساوية من نوع واحد وبأكبر عدد ممكن. كم صندوقًا نحتاج في المجموع؟","We have 78 lemon biscuits, 130 cream biscuits and 156 honey biscuits. We want to fill boxes that are all the same, each with only one type of biscuit and with as many biscuits as possible. How many boxes are needed in total?"),expected:d(14),hint:e("Kalkulatu lehenik kutxa bakoitzeko gaileta kopurua (ZKH), eta gero kutxak.","Calcula primero las galletas por caja (m.c.d.) y después las cajas.","احسب أولًا عدد البسكويت في كل صندوق (ق.م.أ) ثم الصناديق.","First work out the biscuits per box (GCD), then the boxes."),explanation:e("$@GCD(78,130,156)=2\\cdot 13=26$ gaileta kutxako. $3+5+6=14$ kutxa.","$@GCD(78,130,156)=2\\cdot 13=26$ galletas por caja. $3+5+6=14$ cajas.","$@GCD(78,130,156)=2\\cdot 13=26$ بسكويتة في كل صندوق. $3+5+6=14$ صندوقًا.","$@GCD(78,130,156)=2\\cdot 13=26$ biscuits per box. $3+5+6=14$ boxes.")},{id:106,stage:"problems",context:"advanced",points:20,prompt:e("Hiru autobus 8:00etan irten dira batera. Bata 10 minutuz behin irteten da, bestea 15ez behin eta hirugarrena 25ez behin. Zenbat minutu barru irtengo dira berriro batera?","Tres autobuses han salido juntos a las 8:00. Uno sale cada 10 minutos, otro cada 15 y el tercero cada 25. ¿Dentro de cuántos minutos volverán a salir juntos?","انطلقت ثلاث حافلات معًا في الساعة 8:00. الأولى تنطلق كل 10 دقائق والثانية كل 15 والثالثة كل 25. بعد كم دقيقة ستنطلق معًا مجددًا؟","Three buses left together at 8:00. One leaves every 10 minutes, another every 15 and the third every 25. In how many minutes will they leave together again?"),expected:d(150),hint:e("$10=2\\cdot 5$, $15=3\\cdot 5$, $25=5^{2}$.","$10=2\\cdot 5$, $15=3\\cdot 5$, $25=5^{2}$.","$10=2\\cdot 5$، $15=3\\cdot 5$، $25=5^{2}$.","$10=2\\cdot 5$, $15=3\\cdot 5$, $25=5^{2}$."),explanation:e("$@LCM(10,15,25)=2\\cdot 3\\cdot 5^{2}=150$ minutu, hau da, 10:30ean.","$@LCM(10,15,25)=2\\cdot 3\\cdot 5^{2}=150$ minutos, es decir, a las 10:30.","$@LCM(10,15,25)=2\\cdot 3\\cdot 5^{2}=150$ دقيقة، أي في الساعة 10:30.","$@LCM(10,15,25)=2\\cdot 3\\cdot 5^{2}=150$ minutes, that is, at 10:30.")},{id:107,stage:"problems",context:"advanced",points:20,prompt:e("Liburutegi batean 100 eta 140 arteko liburu daude. 4ka, 6ka edo 9ka taldeka daitezke, bat ere soberan gabe. Zenbat liburu daude?","En una biblioteca hay entre 100 y 140 libros. Se pueden agrupar de 4 en 4, de 6 en 6 o de 9 en 9 sin que sobre ninguno. ¿Cuántos libros hay?","في مكتبة ما بين 100 و140 كتابًا. يمكن تجميعها 4 و4 أو 6 و6 أو 9 و9 دون أن يبقى كتاب. كم كتابًا فيها؟","A library has between 100 and 140 books. They can be grouped in 4s, 6s or 9s with none left over. How many books are there?"),expected:d(108),hint:e("Liburu kopurua 4, 6 eta 9ren multiplo komuna da.","El número de libros es múltiplo común de 4, 6 y 9.","عدد الكتب مضاعف مشترك لـ 4 و6 و9.","The number of books is a common multiple of 4, 6 and 9."),explanation:e("$@LCM(4,6,9)=36$. Multiploak: 36, 72, 108, 144… 100 eta 140 artean 108 bakarrik dago.","$@LCM(4,6,9)=36$. Múltiplos: 36, 72, 108, 144… Entre 100 y 140 solo está 108.","$@LCM(4,6,9)=36$. مضاعفاته: 36، 72، 108، 144… وبين 100 و140 يوجد 108 فقط.","$@LCM(4,6,9)=36$. Multiples: 36, 72, 108, 144… Only 108 lies between 100 and 140.")},{id:108,stage:"problems",context:"advanced",points:20,prompt:e("4 mm-ko bola gorriak, 6 mm-ko berdeak eta 8 mm-ko urdinak ditugu. Kolore bakarreko lepokoak egin nahi ditugu, denak luzera berekoak. Gutxienez zenbat mm izango ditu lepoko bakoitzak?","Tenemos bolas rojas de 4 mm, verdes de 6 mm y azules de 8 mm. Queremos hacer collares de un solo color, todos de la misma longitud. ¿Cuántos mm medirá como mínimo cada collar?","لدينا كرات حمراء قطرها 4 مم وخضراء 6 مم وزرقاء 8 مم. نريد صنع عقود بلون واحد وبالطول نفسه. كم مليمترًا على الأقل سيكون طول كل عقد؟","We have red beads of 4 mm, green beads of 6 mm and blue beads of 8 mm. We want to make necklaces of a single colour, all the same length. What is the minimum length, in mm, of each necklace?"),expected:d(24),hint:e("Luzera 4, 6 eta 8ren multiploa da, eta txikiena bilatzen dugu.","La longitud es múltiplo de 4, 6 y 8, y buscamos la menor.","الطول مضاعف لـ 4 و6 و8، ونبحث عن الأصغر.","The length is a multiple of 4, 6 and 8, and we want the smallest one."),explanation:e("$@LCM(4,6,8)=2^{3}\\cdot 3=24$ mm: 6 bola gorri, 4 berde edo 3 urdin lepoko.","$@LCM(4,6,8)=2^{3}\\cdot 3=24$ mm: 6 bolas rojas, 4 verdes o 3 azules por collar.","$@LCM(4,6,8)=2^{3}\\cdot 3=24$ مم: 6 كرات حمراء أو 4 خضراء أو 3 زرقاء في العقد.","$@LCM(4,6,8)=2^{3}\\cdot 3=24$ mm: 6 red beads, 4 green or 3 blue per necklace.")},{id:109,stage:"problems",context:"master",points:30,prompt:e("Monikak 450 argazki baino gutxiago ditu. 8ka, 9ka edo 12ka taldekatzen baditu, ez zaio bat ere soberan geratzen. Gehienez zenbat argazki ditu?","Mónica tiene menos de 450 fotos. Si las agrupa de 8 en 8, de 9 en 9 o de 12 en 12, no le sobra ninguna. ¿Cuántas fotos tiene como máximo?","لدى مونيكا أقل من 450 صورة. إذا جمعتها 8 و8 أو 9 و9 أو 12 و12 لا يبقى شيء. ما أكبر عدد ممكن من الصور لديها؟","Mónica has fewer than 450 photos. If she groups them in 8s, 9s or 12s, none is left over. What is the greatest number of photos she can have?"),expected:d(432),hint:e("Kalkulatu MKT eta bilatu 450 baino txikiagoa den haren multiplorik handiena.","Calcula el m.c.m. y busca su mayor múltiplo menor que 450.","احسب م.م.أ وابحث عن أكبر مضاعف له أصغر من 450.","Work out the LCM and find its largest multiple less than 450."),explanation:e("$@LCM(8,9,12)=2^{3}\\cdot 3^{2}=72$. $450\\mathbin{:}72=6$ eta hondarra 18 → $72\\cdot 6=432$ argazki.","$@LCM(8,9,12)=2^{3}\\cdot 3^{2}=72$. $450\\mathbin{:}72=6$ y resto 18 → $72\\cdot 6=432$ fotos.","$@LCM(8,9,12)=2^{3}\\cdot 3^{2}=72$. $450\\mathbin{:}72=6$ والباقي 18 ← $72\\cdot 6=432$ صورة.","$@LCM(8,9,12)=2^{3}\\cdot 3^{2}=72$. $450\\mathbin{:}72=6$ with remainder 18 → $72\\cdot 6=432$ photos.")},{id:110,stage:"problems",context:"master",points:30,prompt:e("Jonek 200 eta 250 arteko txanpon ditu. 3ka, 5eka edo 7ka taldekatzen baditu, beti 2 soberan geratzen zaizkio. Zenbat txanpon ditu?","Jon tiene entre 200 y 250 monedas. Si las agrupa de 3 en 3, de 5 en 5 o de 7 en 7, siempre le sobran 2. ¿Cuántas monedas tiene?","لدى جون ما بين 200 و250 قطعة نقدية. إذا جمعها 3 و3 أو 5 و5 أو 7 و7 تبقى دائمًا قطعتان. كم قطعة لديه؟","Jon has between 200 and 250 coins. If he groups them in 3s, 5s or 7s, he always has 2 left over. How many coins does he have?"),expected:d(212),hint:e("2 kendu ondoren, 3, 5 eta 7ren multiplo komuna geratzen da.","Quitando las 2 que sobran, queda un múltiplo común de 3, 5 y 7.","بعد طرح القطعتين الزائدتين يبقى مضاعف مشترك لـ 3 و5 و7.","Taking away the 2 left over, what remains is a common multiple of 3, 5 and 7."),explanation:e("$@LCM(3,5,7)=105$. Multiploak: 105, 210, 315… $210+2=212$ bakarrik dago 200 eta 250 artean.","$@LCM(3,5,7)=105$. Múltiplos: 105, 210, 315… Solo $210+2=212$ está entre 200 y 250.","$@LCM(3,5,7)=105$. مضاعفاته: 105، 210، 315… والعدد الوحيد بين 200 و250 هو $210+2=212$.","$@LCM(3,5,7)=105$. Multiples: 105, 210, 315… Only $210+2=212$ lies between 200 and 250.")},{id:111,stage:"problems",context:"master",points:30,prompt:e("35 m × 25 m-ko lokal bat ahalik eta handienak diren aparkaleku karratuetan banatu nahi da. Zenbat aparkaleku aterako dira?","Un local de 35 m × 25 m se quiere dividir en plazas de aparcamiento cuadradas lo más grandes posible. ¿Cuántas plazas saldrán?","نريد تقسيم محل مساحته 35 م × 25 م إلى مواقف سيارات مربعة بأكبر حجم ممكن. كم موقفًا سنحصل عليه؟","A 35 m × 25 m site is to be divided into square parking spaces as large as possible. How many parking spaces will there be?"),expected:d(35),hint:e("Lehenik aldea (ZKH), gero zenbat sartzen diren luzeran eta zabaleran.","Primero el lado (m.c.d.) y después cuántas caben a lo largo y a lo ancho.","أولًا طول الضلع (ق.م.أ) ثم كم موقفًا يتسع طولًا وعرضًا.","First the side (GCD), then how many fit along the length and across the width."),explanation:e("$@GCD(35,25)=5$ m. $35\\mathbin{:}5=7$ eta $25\\mathbin{:}5=5$ → $7\\cdot 5=35$ aparkaleku.","$@GCD(35,25)=5$ m. $35\\mathbin{:}5=7$ y $25\\mathbin{:}5=5$ → $7\\cdot 5=35$ plazas.","$@GCD(35,25)=5$ م. $35\\mathbin{:}5=7$ و$25\\mathbin{:}5=5$ ← $7\\cdot 5=35$ موقفًا.","$@GCD(35,25)=5$ m. $35\\mathbin{:}5=7$ and $25\\mathbin{:}5=5$ → $7\\cdot 5=35$ spaces.")},{id:112,stage:"gcd-lcm",context:"master",points:30,prompt:e("Bi zenbakiren ZKH 6 da eta MKT 72. Zenbakietako bat 18 da. Zein da bestea?","El m.c.d. de dos números es 6 y su m.c.m. es 72. Uno de ellos es 18. ¿Cuál es el otro?","ق.م.أ لعددين هو 6 وم.م.أ هو 72. أحدهما 18. ما العدد الآخر؟","The GCD of two numbers is 6 and their LCM is 72. One of them is 18. What is the other?"),expected:d(24),hint:e("Bi zenbakiren biderkadura = ZKH · MKT.","El producto de los dos números = m.c.d. · m.c.m.","حاصل ضرب العددين = ق.م.أ · م.م.أ.","The product of the two numbers = GCD · LCM."),explanation:e("$18\\cdot b=6\\cdot 72=432$ → $b=24$. Egiaztatu: $@GCD(18,24)=6$ eta $@LCM(18,24)=72$.","$18\\cdot b=6\\cdot 72=432$ → $b=24$. Comprueba: $@GCD(18,24)=6$ y $@LCM(18,24)=72$.","$18\\cdot b=6\\cdot 72=432$ ← $b=24$. تحقّق: $@GCD(18,24)=6$ و$@LCM(18,24)=72$.","$18\\cdot b=6\\cdot 72=432$ → $b=24$. Check: $@GCD(18,24)=6$ and $@LCM(18,24)=72$.")}],pe=[{id:"multiples",title:e("Multiploak eta zatitzaileak","Múltiplos y divisores","المضاعفات والقواسم","Multiples and divisors"),items:[{id:1,difficulty:"easy",question:e("Idatzi 9ren lehen bost multiploak.","Escribe los cinco primeros múltiplos de 9.","اكتب أول خمسة مضاعفات للعدد 9.","Write the first five multiples of 9."),solution:u("$9,\\ 18,\\ 27,\\ 36,\\ 45$")},{id:2,difficulty:"easy",question:e("91 7ren multiploa al da? Eta 85 6rena?","¿Es 91 múltiplo de 7? ¿Y 85 de 6?","هل 91 مضاعف لـ 7؟ وهل 85 مضاعف لـ 6؟","Is 91 a multiple of 7? And 85 a multiple of 6?"),solution:e("Bai: $91=7\\cdot 13$. Ez: $85=6\\cdot 14+1$, hondarra 1 da.","Sí: $91=7\\cdot 13$. No: $85=6\\cdot 14+1$, el resto es 1.","نعم: $91=7\\cdot 13$. لا: $85=6\\cdot 14+1$، والباقي 1.","Yes: $91=7\\cdot 13$. No: $85=6\\cdot 14+1$, the remainder is 1.")},{id:3,difficulty:"easy",question:e("Idatzi 30en zatitzaile guztiak.","Escribe todos los divisores de 30.","اكتب جميع قواسم 30.","Write all the divisors of 30."),solution:u("$@DIV(30)=\\{1,2,3,5,6,10,15,30\\}$")},{id:4,difficulty:"medium",question:e("Idatzi 50 eta 100 arteko 12ren multiploak.","Escribe los múltiplos de 12 comprendidos entre 50 y 100.","اكتب مضاعفات 12 الواقعة بين 50 و100.","Write the multiples of 12 between 50 and 100."),solution:u("$60,\\ 72,\\ 84,\\ 96$")},{id:5,difficulty:"medium",question:e("Idatzi 40 eta 60ren zatitzaile komunak.","Escribe los divisores comunes de 40 y 60.","اكتب القواسم المشتركة لـ 40 و60.","Write the common divisors of 40 and 60."),solution:e("$@DIV(40)=\\{1,2,4,5,8,10,20,40\\}$ eta $@DIV(60)=\\{1,2,3,4,5,6,10,12,15,20,30,60\\}$. Komunak: 1, 2, 4, 5, 10, 20.","$@DIV(40)=\\{1,2,4,5,8,10,20,40\\}$ y $@DIV(60)=\\{1,2,3,4,5,6,10,12,15,20,30,60\\}$. Comunes: 1, 2, 4, 5, 10, 20.","$@DIV(40)=\\{1,2,4,5,8,10,20,40\\}$ و$@DIV(60)=\\{1,2,3,4,5,6,10,12,15,20,30,60\\}$. المشتركة: 1، 2، 4، 5، 10، 20.","$@DIV(40)=\\{1,2,4,5,8,10,20,40\\}$ and $@DIV(60)=\\{1,2,3,4,5,6,10,12,15,20,30,60\\}$. Common: 1, 2, 4, 5, 10, 20.")},{id:6,difficulty:"hard",question:e("Egia ala gezurra? a) 1 zenbaki guztien zatitzailea da. b) 0 zenbaki guztien multiploa da. c) Zenbaki batek infinitu zatitzaile ditu.","¿Verdadero o falso? a) 1 es divisor de todos los números. b) 0 es múltiplo de todos los números. c) Un número tiene infinitos divisores.","صح أم خطأ؟ أ) العدد 1 قاسم لكل الأعداد. ب) الصفر مضاعف لكل الأعداد. ج) للعدد عدد لا نهائي من القواسم.","True or false? a) 1 is a divisor of every number. b) 0 is a multiple of every number. c) A number has infinitely many divisors."),solution:e("a) Egia: $a=1\\cdot a$. b) Egia: $0=a\\cdot 0$. c) Gezurra: zatitzaileak ez dira zenbakia bera baino handiagoak; multiploak dira infinituak.","a) Verdadero: $a=1\\cdot a$. b) Verdadero: $0=a\\cdot 0$. c) Falso: los divisores no superan al número; los que son infinitos son los múltiplos.","أ) صح: $a=1\\cdot a$. ب) صح: $0=a\\cdot 0$. ج) خطأ: القواسم لا تتجاوز العدد؛ المضاعفات هي غير المنتهية.","a) True: $a=1\\cdot a$. b) True: $0=a\\cdot 0$. c) False: divisors are never greater than the number; it is the multiples that are infinite.")}]},{id:"criteria",title:e("Zatigarritasun irizpideak","Criterios de divisibilidad","قواعد قابلية القسمة","Divisibility rules"),items:[{id:7,difficulty:"easy",question:e("2345, 1710 eta 888: zein dira 2rekin, 5ekin eta 10ekin zatigarriak?","2345, 1710 y 888: ¿cuáles son divisibles por 2, por 5 y por 10?","2345 و1710 و888: أيها يقبل القسمة على 2 و5 و10؟","2,345, 1,710 and 888: which of them are divisible by 2, by 5 and by 10?"),solution:e("2345: 5ekin bakarrik. 1710: 2rekin, 5ekin eta 10ekin. 888: 2rekin bakarrik.","2345: solo por 5. 1710: por 2, por 5 y por 10. 888: solo por 2.","2345: على 5 فقط. 1710: على 2 و5 و10. 888: على 2 فقط.","2,345: only by 5. 1,710: by 2, by 5 and by 10. 888: only by 2.")},{id:8,difficulty:"easy",question:e("4131 3rekin zatigarria al da? Eta 9rekin?","¿Es 4131 divisible por 3? ¿Y por 9?","هل 4131 يقبل القسمة على 3؟ وعلى 9؟","Is 4,131 divisible by 3? And by 9?"),solution:e("$4+1+3+1=9$: bai 3rekin eta bai 9rekin.","$4+1+3+1=9$: sí por 3 y sí por 9.","$4+1+3+1=9$: نعم على 3 ونعم على 9.","$4+1+3+1=9$: yes by 3 and yes by 9.")},{id:9,difficulty:"medium",question:e("Osatu $5\\square 4$ 3rekin zatigarria izateko. Idatzi aukera guztiak.","Completa $5\\square 4$ para que sea divisible por 3. Escribe todas las posibilidades.","أكمل $5\\square 4$ ليقبل القسمة على 3. اكتب كل الاحتمالات.","Complete $5\\square 4$ so that it is divisible by 3. Write all the possibilities."),solution:e("$5+4=9$ dagoeneko 3ren multiploa da; zifrak ere hala izan behar du: 504, 534, 564, 594.","$5+4=9$ ya es múltiplo de 3; la cifra también tiene que serlo: 504, 534, 564, 594.","$5+4=9$ مضاعف لـ 3 أصلًا، فيجب أن يكون الرقم كذلك: 504، 534، 564، 594.","$5+4=9$ is already a multiple of 3, so the digit must also be a multiple of 3: 504, 534, 564, 594.")},{id:10,difficulty:"medium",question:e("Aplikatu 11ren irizpidea 7392 zenbakiari.","Aplica el criterio del 11 a 7 392.","طبّق قاعدة 11 على 7392.","Apply the divisibility rule for 11 to 7,392."),solution:e("Posizio bikoitiak: $9+7=16$. Bakoitiak: $2+3=5$. $16-5=11$ → zatigarria da ($7392=11\\cdot 672$).","Lugares pares: $9+7=16$. Impares: $2+3=5$. $16-5=11$ → es divisible ($7392=11\\cdot 672$).","المواقع الزوجية: $9+7=16$. الفردية: $2+3=5$. $16-5=11$ ← يقبل القسمة ($7392=11\\cdot 672$).","Even places: $9+7=16$. Odd places: $2+3=5$. $16-5=11$ → it is divisible ($7\\,392=11\\cdot 672$).")},{id:11,difficulty:"medium",question:e("Aplikatu 7ren irizpidea 1603 zenbakiari.","Aplica el criterio del 7 a 1 603.","طبّق قاعدة 7 على 1603.","Apply the divisibility rule for 7 to 1,603."),solution:e("$160-6=154$; $15-8=7$ → zatigarria da ($1603=7\\cdot 229$).","$160-6=154$; $15-8=7$ → es divisible ($1603=7\\cdot 229$).","$160-6=154$؛ $15-8=7$ ← يقبل القسمة ($1603=7\\cdot 229$).","$160-6=154$; $15-8=7$ → it is divisible ($1\\,603=7\\cdot 229$).")},{id:12,difficulty:"hard",question:e("Idatzi $2\\square 5$ erako zenbaki bat, 5ekin eta 9rekin zatigarria.","Escribe un número de la forma $2\\square 5$ divisible por 5 y por 9.","اكتب عددًا على الصورة $2\\square 5$ يقبل القسمة على 5 و9.","Write a number of the form $2\\square 5$ that is divisible by 5 and by 9."),solution:e("5ean amaitzen da (5 ✓). $2+\\square+5=9$ → $\\square=2$: 225.","Acaba en 5 (5 ✓). $2+\\square+5=9$ → $\\square=2$: 225.","ينتهي بـ 5 (5 ✓). $2+\\square+5=9$ ← $\\square=2$: ‏225.","It ends in 5 (5 ✓). $2+\\square+5=9$ → $\\square=2$: 225."),answer:{expected:d(225)}}]},{id:"primes",title:e("Zenbaki lehenak eta faktorizazioa","Primos y factorización","الأعداد الأولية والتحليل","Primes and factorisation"),items:[{id:13,difficulty:"easy",question:e("Lehena ala konposatua? 37, 39, 41, 51.","¿Primo o compuesto? 37, 39, 41, 51.","أولي أم مؤلف؟ 37، 39، 41، 51.","Prime or composite? 37, 39, 41, 51."),solution:e("37 eta 41 lehenak. $39=3\\cdot 13$ eta $51=3\\cdot 17$ konposatuak.","37 y 41 son primos. $39=3\\cdot 13$ y $51=3\\cdot 17$ son compuestos.","37 و41 أوليان. $39=3\\cdot 13$ و$51=3\\cdot 17$ مؤلفان.","37 and 41 are prime. $39=3\\cdot 13$ and $51=3\\cdot 17$ are composite.")},{id:14,difficulty:"easy",question:e("Deskonposatu 48 biderkagai lehenetan.","Descompón 48 en factores primos.","حلّل 48 إلى عوامل أولية.","Find the prime factorisation of 48."),solution:u("$48=2^{4}\\cdot 3$")},{id:15,difficulty:"medium",question:e("Deskonposatu 180 biderkagai lehenetan.","Descompón 180 en factores primos.","حلّل 180 إلى عوامل أولية.","Find the prime factorisation of 180."),solution:u("$180=2^{2}\\cdot 3^{2}\\cdot 5$")},{id:16,difficulty:"medium",question:e("$90=2\\cdot 5\\cdot 9$ berdintza egia da. 90en biderkagai lehenetako deskonposizioa al da?","La igualdad $90=2\\cdot 5\\cdot 9$ es cierta. ¿Es la descomposición de 90 en factores primos?","المساواة $90=2\\cdot 5\\cdot 9$ صحيحة. هل هي تحليل 90 إلى عوامل أولية؟","The equation $90=2\\cdot 5\\cdot 9$ is true. Is it the prime factorisation of 90?"),solution:e("Ez: biderketa zuzena da, baina 9 ez da lehena ($9=3^{2}$). Deskonposizioa: $90=2\\cdot 3^{2}\\cdot 5$.","No: el producto es correcto, pero 9 no es primo ($9=3^{2}$). La descomposición: $90=2\\cdot 3^{2}\\cdot 5$.","لا: الضرب صحيح، لكن 9 ليس أوليًا ($9=3^{2}$). التحليل: $90=2\\cdot 3^{2}\\cdot 5$.","No: the product is correct, but 9 is not prime ($9=3^{2}$). The prime factorisation: $90=2\\cdot 3^{2}\\cdot 5$.")},{id:17,difficulty:"medium",question:e("Zein zenbaki da $2^{2}\\cdot 5\\cdot 7$?","¿Qué número es $2^{2}\\cdot 5\\cdot 7$?","ما العدد $2^{2}\\cdot 5\\cdot 7$؟","What number is $2^{2}\\cdot 5\\cdot 7$?"),solution:u("$4\\cdot 5\\cdot 7=140$"),answer:{expected:d(140)}},{id:18,difficulty:"hard",question:e("1001 lehena al da? Erabili 7ren irizpidea.","¿Es 1001 primo? Usa el criterio del 7.","هل 1001 أولي؟ استعمل قاعدة 7.","Is 1,001 prime? Use the divisibility rule for 7."),solution:e("$100-2=98=7\\cdot 14$ → 7rekin zatigarria. $1001=7\\cdot 11\\cdot 13$: konposatua.","$100-2=98=7\\cdot 14$ → divisible por 7. $1001=7\\cdot 11\\cdot 13$: compuesto.","$100-2=98=7\\cdot 14$ ← يقبل القسمة على 7. $1001=7\\cdot 11\\cdot 13$: مؤلف.","$100-2=98=7\\cdot 14$ → divisible by 7. $1\\,001=7\\cdot 11\\cdot 13$: composite.")}]},{id:"gcd-lcm",title:e("ZKH eta MKT","m.c.d. y m.c.m.","ق.م.أ و م.م.أ","GCD and LCM"),items:[{id:19,difficulty:"easy",question:e("Kalkulatu zerrendekin $@GCD(8,12)$ eta $@LCM(8,12)$.","Calcula con listas el $@GCD(8,12)$ y el $@LCM(8,12)$.","احسب بالقوائم $@GCD(8,12)$ و$@LCM(8,12)$.","Use lists to work out $@GCD(8,12)$ and $@LCM(8,12)$."),solution:e("$@DIV(8)=\\{1,2,4,8\\}$, $@DIV(12)=\\{1,2,3,4,6,12\\}$ → $@GCD=4$. $\\mathrm{M}(8)=\\{8,16,24,\\dots\\}$, $\\mathrm{M}(12)=\\{12,24,\\dots\\}$ → $@LCM=24$.","$@DIV(8)=\\{1,2,4,8\\}$, $@DIV(12)=\\{1,2,3,4,6,12\\}$ → $@GCD=4$. $\\mathrm{M}(8)=\\{8,16,24,\\dots\\}$, $\\mathrm{M}(12)=\\{12,24,\\dots\\}$ → $@LCM=24$.","$@DIV(8)=\\{1,2,4,8\\}$، $@DIV(12)=\\{1,2,3,4,6,12\\}$ ← $@GCD=4$. $\\mathrm{M}(8)=\\{8,16,24,\\dots\\}$، $\\mathrm{M}(12)=\\{12,24,\\dots\\}$ ← $@LCM=24$.","$@DIV(8)=\\{1,2,4,8\\}$, $@DIV(12)=\\{1,2,3,4,6,12\\}$ → $@GCD=4$. $\\mathrm{M}(8)=\\{8,16,24,\\dots\\}$, $\\mathrm{M}(12)=\\{12,24,\\dots\\}$ → $@LCM=24$.")},{id:20,difficulty:"medium",question:v("$@GCD(60,90)$, $@LCM(60,90)$"),solution:u("$60=2^{2}\\cdot 3\\cdot 5,\\ 90=2\\cdot 3^{2}\\cdot 5\\ \\Rightarrow\\ @GCD=30,\\ @LCM=180$")},{id:21,difficulty:"medium",question:v("$@GCD(84,105)$, $@LCM(84,105)$"),solution:u("$84=2^{2}\\cdot 3\\cdot 7,\\ 105=3\\cdot 5\\cdot 7\\ \\Rightarrow\\ @GCD=21,\\ @LCM=420$")},{id:22,difficulty:"medium",question:v("$@GCD(18,90,360)$, $@LCM(18,90,360)$"),solution:u("$18=2\\cdot 3^{2},\\ 90=2\\cdot 3^{2}\\cdot 5,\\ 360=2^{3}\\cdot 3^{2}\\cdot 5\\ \\Rightarrow\\ @GCD=18,\\ @LCM=360$")},{id:23,difficulty:"hard",question:e("16 eta 25 elkarren arteko lehenak al dira? Kalkulatu haien MKT.","¿Son 16 y 25 primos entre sí? Calcula su m.c.m.","هل 16 و25 أوليان فيما بينهما؟ احسب م.م.أ لهما.","Are 16 and 25 coprime? Work out their LCM."),solution:e("$16=2^{4}$, $25=5^{2}$: ez dute biderkagai komunik, $@GCD=1$ → bai. $@LCM=16\\cdot 25=400$.","$16=2^{4}$, $25=5^{2}$: no tienen factores comunes, $@GCD=1$ → sí. $@LCM=16\\cdot 25=400$.","$16=2^{4}$، $25=5^{2}$: لا عوامل مشتركة، $@GCD=1$ ← نعم. $@LCM=16\\cdot 25=400$.","$16=2^{4}$, $25=5^{2}$: they have no common factors, $@GCD=1$ → yes. $@LCM=16\\cdot 25=400$.")},{id:24,difficulty:"hard",question:e("Egiaztatu 12 eta 18rekin: ZKH · MKT = bi zenbakien biderkadura.","Comprueba con 12 y 18 que m.c.d. · m.c.m. = producto de los dos números.","تحقّق باستعمال 12 و18 أن ق.م.أ · م.م.أ = حاصل ضرب العددين.","Check with 12 and 18 that GCD · LCM = the product of the two numbers."),solution:u("$@GCD(12,18)\\cdot @LCM(12,18)=6\\cdot 36=216=12\\cdot 18$")}]},{id:"problems",title:e("Buruketak","Problemas","المسائل","Problems"),items:[{id:25,difficulty:"easy",question:e("520 cm × 240 cm-ko horma bat ahalik eta handienak diren lauza karratuekin estali nahi da. Zenbat neurtuko du lauzaren aldeak?","Una pared de 520 cm × 240 cm se quiere cubrir con baldosas cuadradas lo más grandes posible. ¿Cuánto medirá el lado de cada baldosa?","نريد تغطية جدار 520 سم × 240 سم ببلاط مربع بأكبر حجم ممكن. كم يكون طول ضلع البلاطة؟","A 520 cm × 240 cm wall is to be covered with square tiles as large as possible. How long will the side of each tile be?"),solution:e("$@GCD(520,240)=2^{3}\\cdot 5=40$: lauza bakoitzak 40 cm-ko aldea izango du.","$@GCD(520,240)=2^{3}\\cdot 5=40$: cada baldosa medirá 40 cm de lado.","$@GCD(520,240)=2^{3}\\cdot 5=40$: طول ضلع كل بلاطة 40 سم.","$@GCD(520,240)=2^{3}\\cdot 5=40$: each tile will have a side of 40 cm."),answer:{expected:d(40)}},{id:26,difficulty:"easy",question:e("Bi semaforo berdean jartzen dira 30 eta 45 segundoro. Batera jarri badira, noiz jarriko dira berriro batera?","Dos semáforos se ponen en verde cada 30 y 45 segundos. Si han coincidido, ¿cuándo volverán a coincidir?","إشارتا مرور تصبحان خضراوين كل 30 و45 ثانية. إذا تزامنتا، فمتى تتزامنان مجددًا؟","Two traffic lights turn green every 30 and 45 seconds. If they have turned green together, when will they next turn green together?"),solution:e("$@LCM(30,45)=2\\cdot 3^{2}\\cdot 5=90$: 90 segundo barru.","$@LCM(30,45)=2\\cdot 3^{2}\\cdot 5=90$: dentro de 90 segundos.","$@LCM(30,45)=2\\cdot 3^{2}\\cdot 5=90$: بعد 90 ثانية.","$@LCM(30,45)=2\\cdot 3^{2}\\cdot 5=90$: in 90 seconds."),answer:{expected:d(90)}},{id:27,difficulty:"medium",question:e("14 ale urdin, 16 laranja eta 10 gorri ditugu. Lepoko berdinak egin nahi ditugu ale guztiekin. Gehienez zenbat lepoko? Zer izango du bakoitzak?","Tenemos 14 cuentas azules, 16 naranjas y 10 rojas. Queremos hacer collares iguales con todas las cuentas. ¿Cuántos collares como máximo? ¿Qué llevará cada uno?","لدينا 14 خرزة زرقاء و16 برتقالية و10 حمراء. نريد صنع عقود متساوية بكل الخرز. ما أكبر عدد من العقود؟ وماذا في كل عقد؟","We have 14 blue beads, 16 orange beads and 10 red beads. We want to make identical necklaces using all the beads. What is the maximum number of necklaces? What will each one contain?"),solution:e("$@GCD(14,16,10)=2$: 2 lepoko, bakoitzak 7 urdin, 8 laranja eta 5 gorri.","$@GCD(14,16,10)=2$: 2 collares, cada uno con 7 azules, 8 naranjas y 5 rojas.","$@GCD(14,16,10)=2$: عقدان، في كل منهما 7 زرقاء و8 برتقالية و5 حمراء.","$@GCD(14,16,10)=2$: 2 necklaces, each with 7 blue, 8 orange and 5 red beads.")},{id:28,difficulty:"medium",question:e("55 mm-ko kubo urdinekin eta 45 mm-ko kubo gorriekin bi zutabe egiten ditugu. Noiz izango dute altuera bera lehen aldiz? Zenbat kubo zutabe bakoitzean?","Con cubos azules de 55 mm y rojos de 45 mm hacemos dos columnas. ¿Cuándo tendrán por primera vez la misma altura? ¿Cuántos cubos tendrá cada una?","نبني عمودين: أحدهما بمكعبات زرقاء ارتفاعها 55 مم والآخر بمكعبات حمراء 45 مم. متى يتساوى ارتفاعهما لأول مرة؟ وكم مكعبًا في كل عمود؟","We build two stacks, one of blue cubes of 55 mm and one of red cubes of 45 mm. When will they first be the same height? How many cubes will each one have?"),solution:e("$@LCM(55,45)=3^{2}\\cdot 5\\cdot 11=495$ mm. Urdinak: $495\\mathbin{:}55=9$ kubo; gorriak: $495\\mathbin{:}45=11$ kubo.","$@LCM(55,45)=3^{2}\\cdot 5\\cdot 11=495$ mm. Azules: $495\\mathbin{:}55=9$ cubos; rojos: $495\\mathbin{:}45=11$ cubos.","$@LCM(55,45)=3^{2}\\cdot 5\\cdot 11=495$ مم. الزرقاء: $495\\mathbin{:}55=9$ مكعبات؛ الحمراء: $495\\mathbin{:}45=11$ مكعبًا.","$@LCM(55,45)=3^{2}\\cdot 5\\cdot 11=495$ mm. Blue: $495\\mathbin{:}55=9$ cubes; red: $495\\mathbin{:}45=11$ cubes.")},{id:29,difficulty:"hard",question:e("36 txorizo-ogitarteko eta 84 gazta-ogitarteko ditugu. Poltsa berdinak egin nahi ditugu, mota bakarrekoak eta ahalik eta handienak. Zenbat poltsa?","Tenemos 36 bocadillos de chorizo y 84 de queso. Queremos bolsas iguales, de un solo tipo y lo más grandes posible. ¿Cuántas bolsas?","لدينا 36 شطيرة بالنقانق و84 بالجبن. نريد أكياسًا متساوية من نوع واحد وبأكبر حجم ممكن. كم كيسًا؟","We have 36 chorizo sandwiches and 84 cheese sandwiches. We want bags that are all the same, each with only one type of sandwich, and as large as possible. How many bags?"),solution:e("$@GCD(36,84)=12$ ogitarteko poltsako. $36\\mathbin{:}12=3$ eta $84\\mathbin{:}12=7$ → 10 poltsa.","$@GCD(36,84)=12$ bocadillos por bolsa. $36\\mathbin{:}12=3$ y $84\\mathbin{:}12=7$ → 10 bolsas.","$@GCD(36,84)=12$ شطيرة في الكيس. $36\\mathbin{:}12=3$ و$84\\mathbin{:}12=7$ ← 10 أكياس.","$@GCD(36,84)=12$ sandwiches per bag. $36\\mathbin{:}12=3$ and $84\\mathbin{:}12=7$ → 10 bags."),answer:{expected:d(10)}},{id:30,difficulty:"hard",question:e("Hiru txirrindularik itzuli bat 12, 15 eta 20 minututan egiten dute. 10:00etan batera irten dira. Noiz igaroko dira berriro batera irteera-lerrotik?","Tres ciclistas dan una vuelta en 12, 15 y 20 minutos. Salen juntos a las 10:00. ¿Cuándo volverán a pasar juntos por la salida?","ثلاثة دراجين يُكملون لفة في 12 و15 و20 دقيقة. انطلقوا معًا في الساعة 10:00. متى يمرون معًا بخط الانطلاق مجددًا؟","Three cyclists complete a lap in 12, 15 and 20 minutes. They set off together at 10:00. When will they next pass the start together?"),solution:e("$@LCM(12,15,20)=2^{2}\\cdot 3\\cdot 5=60$ minutu → 11:00etan.","$@LCM(12,15,20)=2^{2}\\cdot 3\\cdot 5=60$ minutos → a las 11:00.","$@LCM(12,15,20)=2^{2}\\cdot 3\\cdot 5=60$ دقيقة ← في الساعة 11:00.","$@LCM(12,15,20)=2^{2}\\cdot 3\\cdot 5=60$ minutes → at 11:00.")}]}],he=[["divisors-without-n","divisors-without-one","one-as-prime","exponent-lost"],["gcd-greatest-exponents","lcm-smallest-exponents","lcm-common-only","product-as-lcm"],["gcd-instead-of-lcm","lcm-instead-of-gcd","length-not-pieces","minutes-not-laps"]],G=6,r=(i,s,a,t)=>({eu:i,es:s,en:t,ar:a}),m=(i,s)=>({label:i,latex:s}),l={pairs:r("Bikoteak","Parejas","الأزواج","Pairs"),divisors:r("Zatitzaileak","Divisores","القواسم","Divisors"),count:r("Zenbat","Cuántos","كم","How many"),primes:r("Lehenak","Primos","الأعداد الأولية","Primes"),split:r("Deskonposatu","Descompón","حلّل","Split"),factorisation:r("Faktorizazioa","Factorización","التحليل","Factorisation"),gcd:r("ZKH","m.c.d.","ق.م.أ","GCD"),lcm:r("MKT","m.c.m.","م.م.أ","LCM"),what:r("Zer bilatzen da","Qué se busca","ما المطلوب","What we look for"),answer:r("Erantzuna","Respuesta","الجواب","Answer")},ke={"divisors-without-n":r("Zenbakia bera ez du zatitzaileen artean jarri","No puso el propio número entre sus divisores","لم يضع العدد نفسه بين قواسمه","Left the number itself out of its divisors"),"divisors-without-one":r("1 ez du zatitzaileen artean jarri","No puso el 1 entre los divisores","لم يضع 1 بين القواسم","Left 1 out of the divisors"),"one-as-prime":r("1 zenbaki lehentzat hartu du","Contó el 1 como número primo","عدّ 1 عددًا أوليًا","Counted 1 as a prime number"),"exponent-lost":r("Faktorizazioan berretzaile bat galdu du","Perdió un exponente en la factorización","أضاع أسًا في التحليل","Lost an exponent in the factorisation"),"gcd-greatest-exponents":r("ZKHan berretzaile handienak hartu ditu","En el m.c.d. tomó los exponentes mayores","أخذ في ق.م.أ الأسس الكبرى","Took the greatest exponents for the GCD"),"lcm-smallest-exponents":r("MKTan berretzaile txikienak hartu ditu","En el m.c.m. tomó los exponentes menores","أخذ في م.م.أ الأسس الصغرى","Took the smallest exponents for the LCM"),"lcm-common-only":r("MKTan faktore komunak bakarrik hartu ditu","En el m.c.m. tomó solo los factores comunes","أخذ في م.م.أ العوامل المشتركة فقط","Took only the common factors for the LCM"),"product-as-lcm":r("Bi zenbakien biderkadura MKTtzat hartu du","Tomó el producto de los dos números como m.c.m.","اعتبر جداء العددين م.م.أ","Took the product of the two numbers as the LCM"),"gcd-instead-of-lcm":r("MKT behar zen eta ZKH kalkulatu du","Hacía falta el m.c.m. y calculó el m.c.d.","كان المطلوب م.م.أ فحسب ق.م.أ","Needed the LCM and worked out the GCD"),"lcm-instead-of-gcd":r("ZKH behar zen eta MKT kalkulatu du","Hacía falta el m.c.d. y calculó el m.c.m.","كان المطلوب ق.م.أ فحسب م.م.أ","Needed the GCD and worked out the LCM"),"length-not-pieces":r("Zatien luzera eman du, zenbat zati diren beharrean","Dio la longitud de los trozos, no cuántos hay","أعطى طول القطع لا عددها","Gave the length of the pieces, not how many there are"),"minutes-not-laps":r("Minutuak eman ditu, buelta kopurua beharrean","Dio los minutos, no el número de vueltas","أعطى الدقائق لا عدد الدورات","Gave the minutes, not the number of laps")},ze={"divisors-without-n":r("Zenbaki oro bere buruaren zatitzailea da: $18\\div 18=1$.","Todo número es divisor de sí mismo: $18\\div 18=1$.","كل عدد قاسم لنفسه: $18\\div 18=1$.","Every number divides itself: $18\\div 18=1$."),"divisors-without-one":r("1 zenbaki guztien zatitzailea da.","El 1 es divisor de todos los números.","العدد 1 قاسم لكل الأعداد.","1 divides every number."),"one-as-prime":r("Zenbaki lehenak bi zatitzaile ditu zehazki; 1 zenbakiak bakarra du.","Un primo tiene exactamente dos divisores; el 1 solo tiene uno.","للعدد الأولي قاسمان بالضبط؛ وللعدد 1 قاسم واحد.","A prime has exactly two divisors; 1 has only one."),"exponent-lost":r("Egiaztatu biderkatuz: faktorizazioak zenbakia bera eman behar du.","Comprueba multiplicando: la factorización tiene que dar el número.","تحقّق بالضرب: يجب أن يعطي التحليل العدد نفسه.","Check by multiplying: the factorisation must give the number back."),"gcd-greatest-exponents":r("ZKH: faktore komunak, berretzaile txikienarekin.","m.c.d.: factores comunes con el menor exponente.","ق.م.أ: العوامل المشتركة بأصغر أس.","GCD: the common factors with the smallest exponent."),"lcm-smallest-exponents":r("MKT: faktore guztiak, berretzaile handienarekin.","m.c.m.: todos los factores con el mayor exponente.","م.م.أ: كل العوامل بأكبر أس.","LCM: every factor with the greatest exponent."),"lcm-common-only":r("MKTan faktore guztiak sartzen dira, komunak eta ez-komunak.","En el m.c.m. entran todos los factores, comunes y no comunes.","تدخل في م.م.أ كل العوامل المشتركة وغير المشتركة.","The LCM takes every factor, common and not common."),"product-as-lcm":r("Biderkadura multiplo komuna da, baina ez beti txikiena.","El producto es un múltiplo común, pero no siempre el menor.","الجداء مضاعف مشترك لكنه ليس الأصغر دائمًا.","The product is a common multiple, but not always the smallest."),"gcd-instead-of-lcm":r("Noiz egingo dute topo berriro? Bien multiploa: MKT.","¿Cuándo vuelven a coincidir? Un múltiplo de los dos: m.c.m.","متى يلتقيان مجددًا؟ مضاعف للاثنين: م.م.أ.","When do they meet again? A multiple of both: the LCM."),"lcm-instead-of-gcd":r("Zati berdin eta ahalik eta handienak? Bien zatitzailea: ZKH.","¿Trozos iguales y lo más grandes posible? Un divisor de los dos: m.c.d.","قطع متساوية وأكبر ما يمكن؟ قاسم للاثنين: ق.م.أ.","Equal pieces, as large as possible? A divisor of both: the GCD."),"length-not-pieces":r("ZKHk zati baten luzera ematen du; zatiak zenbatzeko, zatitu luzera osoak.","El m.c.d. da la longitud de un trozo; para contarlos, divide las longitudes.","ق.م.أ يعطي طول القطعة؛ ولعدّ القطع نقسم الأطوال.","The GCD gives the length of a piece; to count them, divide the lengths."),"minutes-not-laps":r("MKTk minutuak ematen ditu; bueltak = minutuak zati buelta baten denbora.","El m.c.m. da los minutos; vueltas = minutos entre lo que tarda una vuelta.","م.م.أ يعطي الدقائق؛ الدورات = الدقائق ÷ زمن الدورة.","The LCM gives the minutes; laps = minutes ÷ the time for one lap.")}